bool isPalindrome(const string& s, int l, int r) {
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++; r--;
    }
    return true;
}

// try every (l, r) pair: O(n^2) pairs * O(n) check = O(n^3) total

int expand(const string& s, int l, int r) {
    while (l >= 0 && r < (int)s.size() && s[l] == s[r]) {
        l--; r++;
    }
    return r - l - 1; // length of the palindrome found
}

string longestPalindromeExpand(const string& s) {
    int start = 0, maxLen = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        int len1 = expand(s, i, i);       // odd length, center at i
        int len2 = expand(s, i, i + 1);   // even length, center between i and i+1
        int len = max(len1, len2);
        if (len > maxLen) {
            maxLen = len;
            start = i - (len - 1) / 2;
        }
    }
    return s.substr(start, maxLen);
}

#include <string>
#include <vector>
#include <algorithm>
using namespace std;

string longestPalindrome(string s) {
    if (s.empty()) return "";

    // Step 1: transform so every palindrome has odd length with one center
    string t = "#";
    for (char c : s) {
        t += c;
        t += '#';
    }

    int n = (int)t.size();
    vector<int> P(n, 0);
    int C = 0, R = 0;   // center and right boundary of the rightmost palindrome found so far

    for (int i = 0; i < n; i++) {
        if (i < R) {
            int mirror = 2 * C - i;
            P[i] = min(R - i, P[mirror]);
        }

        // try to expand past whatever the mirror trick already guaranteed
        while (i - P[i] - 1 >= 0 && i + P[i] + 1 < n &&
               t[i - P[i] - 1] == t[i + P[i] + 1]) {
            P[i]++;
        }

        // this palindrome reaches further right than any seen so far
        if (i + P[i] > R) {
            C = i;
            R = i + P[i];
        }
    }

    // Step 2: locate the largest radius
    int maxLen = 0, centerIndex = 0;
    for (int i = 0; i < n; i++) {
        if (P[i] > maxLen) {
            maxLen = P[i];
            centerIndex = i;
        }
    }

    // Step 3: convert back to an index and length in the original string
    int start = (centerIndex - maxLen) / 2;
    return s.substr(start, maxLen);
}
